WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, attributes, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ship_to.city AS ship_city, FORALL(items, i -> i.qty <= 5) AS all_small_qty, attributes['gift'] AS gift FROM carts) SELECT ship_city, COUNT_IF(ship_city = 'Chiang Mai') AS chiang_mai_events, MIN(created_at) AS first_created_at, COUNT(*) FILTER (WHERE ship_city = 'New York') AS new_york_rows, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, MIN(created_at) AS first_created_at_2, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM flattened_attrs GROUP BY ship_city ORDER BY new_york_rows NULLS FIRST;
